(function(){
'use strict';
var held={},callback=null,keys={ArrowUp:'up',KeyW:'up',ArrowDown:'down',KeyS:'down',ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right'};
function init(fn){callback=fn;window.addEventListener('keydown',function(e){if(keys[e.code]){held[keys[e.code]]=true;e.preventDefault();}if(e.code==='ShiftLeft'||e.code==='ShiftRight')held.sprint=true;if((e.code==='KeyE'||e.code==='Space')&&!e.repeat){e.preventDefault();if(callback)callback('interact');}if((e.code==='KeyP'||e.code==='Escape')&&!e.repeat){e.preventDefault();if(callback)callback('pause');}});window.addEventListener('keyup',function(e){if(keys[e.code])held[keys[e.code]]=false;if(e.code==='ShiftLeft'||e.code==='ShiftRight')held.sprint=false;});window.addEventListener('blur',clear);document.querySelectorAll('[data-move]').forEach(function(b){var dir=b.getAttribute('data-move');b.addEventListener('pointerdown',function(e){e.preventDefault();held[dir]=true;b.setPointerCapture(e.pointerId);});['pointerup','pointercancel','lostpointercapture'].forEach(function(v){b.addEventListener(v,function(){held[dir]=false;});});});document.addEventListener('visibilitychange',function(){if(document.hidden)clear();});}
function clear(){held={};}
function vector(){var x=(held.right?1:0)-(held.left?1:0),y=(held.down?1:0)-(held.up?1:0),m=Math.hypot(x,y)||1;return{x:x/m,y:y/m,sprint:!!held.sprint};}
window.SSControls={init:init,vector:vector,clear:clear};
})();